import { useRef, useState } from 'react';
import { TokenSearchField } from '@kerfjs/ui/token-search-field';
import '@kerfjs/ui/layout.css';

type Token = { id: string; label: string; value: string };
type SearchValue = { text: string; tokens: Token[] };
type Selection = { start: number; end: number };
type Suggestion = { id: string; label: string; token: Token };
type Props = {
 value: SearchValue;
 onChange: (value: SearchValue) => void;
 parse: (text: string, tokens: Token[]) => SearchValue;
 suggest: (text: string, tokens: Token[]) => Suggestion[];
};

// Parsing, suggestion identity and persistence are application concerns.
// TokenSearchField owns the single editor's token navigation and focus behavior.
export function ProjectSearch({ value, onChange, parse, suggest }: Props) {
 const [announcement, setAnnouncement] = useState('');
 const [editing, setEditing] = useState<string | null>(null);
 const selection = useRef<Selection>({ start: 0, end: 0 });
 const [restoreSelection, setRestoreSelection] = useState<Selection | undefined>();
 function restore() { setRestoreSelection({ ...selection.current }); }
 function replace(token: Token) {
   const index = value.tokens.findIndex(candidate => candidate.id === editing);
   const tokens = value.tokens.slice();
   if (index >= 0) tokens[index] = { ...token, id: tokens[index].id };
   else tokens.push(token);
   onChange({ text: value.text, tokens }); setEditing(null);
   setAnnouncement(index >= 0 ? 'Filter replaced: ' + token.label : 'Filter added: ' + token.label);
   restore();
 }
 return <div className="kui-layout">
   <TokenSearchField aria-label="Search projects and filters"
     value={value.text}
     tokens={value.tokens}
     onChange={(text: string) => onChange({ ...value, text })}
     onSelectionChange={(next: Selection) => { selection.current = next; }}
     selection={restoreSelection}
     onCommit={() => { onChange(parse(value.text, value.tokens)); restore(); }}
     onTokenRemove={(id: string) => {
       const removed = value.tokens.find(token => token.id === id);
       onChange({ ...value, tokens: value.tokens.filter(token => token.id !== id) });
       setAnnouncement('Removed filter: ' + (removed?.label ?? id)); restore();
     }}
     onTokenEdit={(id: string) => { setEditing(id); setAnnouncement('Choose a replacement filter.'); }}
     suggestions={suggest(value.text, value.tokens)}
     onSuggestionSelect={(suggestion: Suggestion) => replace(suggestion.token)}
     onClear={() => {
       onChange({ text: '', tokens: [] }); setEditing(null);
       selection.current = { start: 0, end: 0 }; restore(); setAnnouncement('Search cleared.');
     }}
   />
   <span role="status" aria-live="polite">{announcement}</span>
 </div>;
}
